// Daily Morning Stock Scan Code Node - FIXED VERSION
// Triggers at 8 AM daily to find best weekly opportunities

// Get current date and market context
const now = new Date();
const dayOfWeek = now.toLocaleDateString('en-US', { weekday: 'long' });
const currentDate = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const currentHour = now.getHours();

// Calculate days until Friday (market week end)
const daysUntilFriday = (5 - now.getDay() + 7) % 7 || 7;
const weekEndDate = new Date(now.getTime() + (daysUntilFriday * 24 * 60 * 60 * 1000));

// Define key market events and catalysts to check
const marketCatalysts = {
  monday: [
    "weekend news and geopolitical developments",
    "pre-market momentum from Asian markets",
    "weekly earnings preview"
  ],
  tuesday: [
    "early week momentum continuation",
    "sector rotation signals",
    "economic data releases"
  ],
  wednesday: [
    "Fed minutes or central bank news",
    "mid-week technical breakouts",
    "options flow analysis"
  ],
  thursday: [
    "weekly jobless claims impact",
    "pre-Friday positioning",
    "earnings reports analysis"
  ],
  friday: [
    "weekly options expiration",
    "end-of-week profit taking",
    "weekend event risks"
  ]
};

// Key sectors and themes to analyze
const hotSectors = [
  "AI and semiconductor stocks",
  "Defense and aerospace (geopolitical tensions)",
  "Clean energy and EV stocks",
  "Biotech with FDA catalysts",
  "Fintech and digital banking",
  "Space and satellite technology",
  "Cybersecurity",
  "Quantum computing"
];

// Specific screening criteria for the week
const screeningCriteria = {
  technical: [
    "Stocks breaking out of consolidation patterns",
    "Names approaching 52-week highs with volume",
    "Oversold bounces (RSI < 30 recovering)",
    "Stocks above all major moving averages"
  ],
  fundamental: [
    "Companies reporting earnings this week",
    "Recent insider buying activity",
    "Analyst upgrades in past 48 hours",
    "New contract wins or partnerships"
  ],
  sentiment: [
    "Unusual options activity",
    "High social media momentum",
    "Increasing Google search trends",
    "Reddit/WSB gaining mentions"
  ]
};

// Get historical data using correct syntax
const staticData = $getWorkflowStaticData('global');
const lastWeekTopPick = staticData.lastWeekTopPick || null;
const previousScanAccuracy = staticData.scanAccuracy || "N/A";

// Build the comprehensive analysis request
const morningAnalysisRequest = {
  messageText: `Perform a comprehensive morning market scan for ${currentDate}. Find the 5 best stock opportunities for this week (ending ${weekEndDate.toLocaleDateString()}). 

ANALYSIS REQUIREMENTS:
1. Check ${marketCatalysts[dayOfWeek.toLowerCase()]?.join(", ") || "today's market catalysts"}
2. Focus on these hot sectors: ${hotSectors.slice(0, 4).join(", ")}
3. Screen for: ${screeningCriteria.technical[0]}, ${screeningCriteria.fundamental[0]}, ${screeningCriteria.sentiment[0]}
4. Prioritize stocks with catalysts happening THIS WEEK
5. Include at least 2 under-the-radar picks (market cap < $10B)

RESEARCH APPROACH:
- Start with Perplexity for deep sector analysis
- Search: "best ${hotSectors[0]} stocks this week catalysts ${currentDate}"
- Then validate with Tavily for breaking news
- Check Reddit sentiment and Google Trends

SEARCH PRIORITIES:
- Pre-market movers showing unusual volume
- Stocks with earnings this week
- Recent news catalysts (last 48 hours)
- Technical breakouts on daily/weekly charts
- Unusual options flow indicating institutional interest

FORMAT: Provide your standard weekly picks format with specific catalysts and dates.`,

  context: {
    scanType: "morning_market_scan",
    dayOfWeek: dayOfWeek,
    currentDate: currentDate,
    daysUntilWeekEnd: daysUntilFriday,
    marketSession: currentHour < 9.5 ? "pre-market" : currentHour < 16 ? "market-hours" : "after-hours",
    prioritySectors: hotSectors.slice(0, 4),
    scanDepth: "comprehensive"
  },

  additionalInstructions: [
    "Use Perplexity FIRST with query: 'best performing stocks this week " + currentDate + " with catalysts'",
    "Then use Tavily for 'stock market pre-market movers today unusual volume'",
    "Check Reddit for 'DD' (due diligence) posts from last 24 hours",
    "Search for 'earnings calendar this week surprise potential'",
    "Look for 'FDA approval calendar' if including biotech",
    "Use Google Trends to verify momentum on top picks",
    "MUST use Think tool to validate all picks before responding"
  ],

  outputRequirements: {
    mustInclude: [
      "Specific catalyst with date",
      "Why this week is critical",
      "Risk/reward assessment",
      "Price target for the week",
      "Volume confirmation"
    ],
    format: "mobile-friendly with emojis",
    tone: "confident but includes risk warnings"
  },

  // Historical performance tracking (for learning)
  lastWeekTopPick: lastWeekTopPick,
  previousScanAccuracy: previousScanAccuracy
};

// Add pre-market specific searches if before market open
if (currentHour < 9.5) {
  morningAnalysisRequest.additionalInstructions.push(
    "Check pre-market gainers showing >5% moves with volume",
    "Look for overnight news from Asian/European markets",
    "Search for pre-market trading alerts and unusual activity"
  );
}

// Add day-specific focus areas
switch(dayOfWeek.toLowerCase()) {
  case 'monday':
    morningAnalysisRequest.additionalInstructions.push(
      "Check weekend news for major developments",
      "Look for stocks gapping up/down from Friday close"
    );
    break;
  case 'friday':
    morningAnalysisRequest.additionalInstructions.push(
      "Focus on weekly options expiration plays",
      "Check for stocks that could run into close"
    );
    break;
}

// Get existing scan log or create new
const existingScans = staticData.morningScans || [];
const scanLog = [...existingScans];

scanLog.push({
  date: currentDate,
  timestamp: now.toISOString(),
  dayOfWeek: dayOfWeek
});

// Keep only last 30 scans
while (scanLog.length > 30) {
  scanLog.shift();
}

// Update static data
const updatedStaticData = {
  ...staticData,
  morningScans: scanLog
};

// $storeWorkflowStaticData('global', updatedStaticData);

// Return the formatted request for the AI Agent
return {
  json: {
    ...morningAnalysisRequest,
    // Additional metadata for routing
    triggerType: "scheduled_morning_scan",
    priority: "high",
    expectedResponseTime: "5-10 minutes",
    notificationSettings: {
      sendSummaryTo: "admin", // Can be configured to send to specific numbers
      includeChart: true
    }
  }
};
// Add to your morning scan code node

// Forex-specific catalysts
const forexCatalysts = {
  monday: [
    "Weekend gap opportunities",
    "Asian session momentum",
    "Week ahead economic calendar"
  ],
  tuesday: [
    "RBA/RBNZ decisions (AUD/NZD pairs)",
    "UK economic data (GBP pairs)"
  ],
  wednesday: [
    "US crude oil inventories (CAD pairs)",
    "FOMC minutes (USD pairs)"
  ],
  thursday: [
    "ECB decisions (EUR pairs)",
    "US jobless claims (USD pairs)"
  ],
  friday: [
    "NFP preparation (USD volatility)",
    "Weekend position adjustments"
  ]
};

// High-impact events this week
const majorForexEvents = [
  "Central bank meetings (Fed, ECB, BoE, BoJ)",
  "Employment data (NFP, ADP, Unemployment)",
  "Inflation data (CPI, PPI)",
  "GDP releases",
  "Retail sales"
];

// Enhanced analysis request
const enhancedAnalysisRequest = {
  messageText: `Perform a comprehensive morning scan for BOTH stocks and forex for ${currentDate}. 

STOCK ANALYSIS:
${morningAnalysisRequest.messageText}

FOREX ANALYSIS:
1. Check ${forexCatalysts[dayOfWeek.toLowerCase()]?.join(", ")}
2. Focus on pairs with high-impact events this week
3. Include both major pairs (EUR/USD, GBP/USD) and interesting crosses
4. Look for technical breakouts aligning with fundamentals
5. Consider carry trade opportunities

CORRELATION ANALYSIS:
- How will this week's events affect both markets?
- Any sector/currency correlations to exploit?

Provide top 3 stocks AND top 2 forex opportunities.`,

  context: {
    ...morningAnalysisRequest.context,
    includeForex: true,
    majorEvents: majorForexEvents
  }
};

// Determine if user wants forex
const isForexQuery = messageText.match(/forex|fx|currency|eur|gbp|jpy|usd/i);
const isStockQuery = messageText.match(/stock|ticker|company|sector/i);
const queryType = isForexQuery && !isStockQuery ? 'forex' : 
                 !isForexQuery && isStockQuery ? 'stocks' : 
                 'both';
